package br.com.onda;
import android.app.*;
import android.content.*;
import android.net.Uri;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;

@androidx.media3.common.util.UnstableApi
public class BackupActivity extends Activity {
 private static final int EXPORT=801,IMPORT=802;private final ExecutorService worker=Executors.newSingleThreadExecutor();private Button export,restore;private TextView status;private boolean busy;
 @Override public void onCreate(Bundle state){super.onCreate(state);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);Ui.background(root);root.setOnApplyWindowInsetsListener((v,i)->{root.setPadding(Ui.dp(this,20),Ui.dp(this,12)+i.getSystemWindowInsetTop(),Ui.dp(this,20),Ui.dp(this,12)+i.getSystemWindowInsetBottom());return i;});setContentView(root);
  LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);Button back=Ui.button(this,"‹",v->finish());back.setContentDescription("Voltar do backup");Ui.ghost(back);header.addView(back,new LinearLayout.LayoutParams(Ui.dp(this,48),Ui.dp(this,48)));TextView title=Ui.text(this,"Backup e restauração",22,Ui.TEXT);Ui.bold(title);header.addView(title,new LinearLayout.LayoutParams(0,-2,1));root.addView(header);
  ScrollView scroll=new ScrollView(this);LinearLayout content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));TextView intro=Ui.text(this,"Guarde suas playlists, favoritas e frases de voz em um arquivo. Você escolhe onde salvar: no celular ou em um serviço disponível no seletor do Android.",15,Ui.TEXT);intro.setPadding(0,Ui.dp(this,20),0,Ui.dp(this,20));content.addView(intro);
  export=Ui.button(this,"Exportar backup",v->pick(true));export.setContentDescription("Exportar backup do Onda");Ui.primary(export);content.addView(export,new LinearLayout.LayoutParams(-1,Ui.dp(this,52)));restore=Ui.button(this,"Restaurar backup",v->pick(false));restore.setContentDescription("Restaurar backup do Onda");LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-1,Ui.dp(this,52));rp.topMargin=Ui.dp(this,12);content.addView(restore,rp);
  status=Ui.text(this,"Nenhuma operação em andamento.",14,Ui.CYAN);status.setContentDescription("Estado do backup");status.setPadding(0,Ui.dp(this,20),0,Ui.dp(this,20));content.addView(status);
  content.addView(Ui.text(this,"O backup contém os nomes das músicas e suas listas, favoritas e frases; os arquivos de áudio não são incluídos. Para trocar de celular, copie também suas músicas e permita o acesso à biblioteca antes de restaurar.\n\nA restauração acrescenta os dados sem apagar os atuais. Listas com o mesmo nome são combinadas. Faixas ausentes ou ambíguas não são associadas; você poderá importar o mesmo backup novamente depois de copiar as músicas.\n\nA prévia aparece antes da confirmação. O arquivo não é criptografado: escolha um local de sua confiança. Histórico, fila, posição, ajustes de som e vídeos não fazem parte desta versão do backup. Limite: 8 MB.",13,Ui.MUTED));
 }
 private void setBusy(boolean value,String message){busy=value;export.setEnabled(!value);restore.setEnabled(!value);status.setText(message);}
 private void pick(boolean create){if(busy)return;Intent i=new Intent(create?Intent.ACTION_CREATE_DOCUMENT:Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(create?"application/json":"*/*");if(create)i.putExtra(Intent.EXTRA_TITLE,"Onda-backup.json");i.putExtra(android.provider.DocumentsContract.EXTRA_INITIAL_URI,android.provider.DocumentsContract.buildDocumentUri("com.android.externalstorage.documents","primary:Download"));try{startActivityForResult(i,create?EXPORT:IMPORT);}catch(ActivityNotFoundException e){status.setText("Nenhum seletor de arquivos disponível neste aparelho.");}}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();if(request==EXPORT)write(uri);else if(request==IMPORT)read(uri);}
 private void write(Uri uri){setBusy(true,"Preparando backup…");worker.execute(()->{try{BackupData.Archive a=BackupStore.snapshot(this);String json=BackupData.json(a);BackupData.parse(json);byte[] bytes=json.getBytes(StandardCharsets.UTF_8);if(bytes.length>BackupData.MAX_BYTES)throw new IOException("O backup excede 8 MB.");if(Thread.currentThread().isInterrupted())return;try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException();out.write(bytes);}ui(()->setBusy(false,"Backup exportado: "+a.lists.size()+" playlists, "+a.favorites.size()+" favoritas e "+a.phrases.entries.size()+" frases.\n"+a.unavailable+" referências a arquivos indisponíveis não foram exportadas."));}catch(Exception e){error("Não foi possível exportar. Verifique o acesso às músicas, o destino e o limite de 8 MB.");}});}
 private void read(Uri uri){setBusy(true,"Lendo e conferindo o backup…");worker.execute(()->{try{byte[] buffer=new byte[8192];ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException();int n;while((n=in.read(buffer))!=-1){if(Thread.currentThread().isInterrupted())return;if(out.size()+n>BackupData.MAX_BYTES)throw new IOException();out.write(buffer,0,n);}}BackupData.Archive a=BackupData.parse(new String(out.toByteArray(),StandardCharsets.UTF_8));List<BackupData.Track> available=BackupStore.tracks(this);BackupData.Plan plan=BackupStore.plan(this,a,available);ui(()->{setBusy(false,"Backup válido. Confira a prévia antes de restaurar.");new AlertDialog.Builder(this).setTitle("Conferir restauração").setMessage(plan.summary()).setNegativeButton("Cancelar",null).setPositiveButton("Restaurar",(d,w)->{setBusy(true,"Restaurando…");worker.execute(()->{try{BackupData.Plan fresh=BackupStore.plan(this,a,available);ui(()->{BackupStore.apply(this,fresh);setBusy(false,"Restauração concluída.\n\n"+fresh.summary().replace("Serão acrescentadas:","Acrescentados:"));android.util.Log.d("OndaBackup","restored lists="+fresh.addedLists+" favorites="+fresh.addedFavorites+" phrases="+fresh.addedPhrases);});}catch(Exception e){error("Não foi possível preparar a restauração. Nenhum dado foi alterado.");}});}).show();});}catch(Exception e){error("O arquivo não é um backup válido do Onda ou o acesso à biblioteca não foi permitido. Nenhum dado foi alterado.");}});}
 private void error(String message){ui(()->setBusy(false,message));}
 private void ui(Runnable task){runOnUiThread(()->{if(!isDestroyed()&&!isFinishing())task.run();});}
 @Override public void onDestroy(){worker.shutdownNow();super.onDestroy();}
}
